import{z as d,x as i,o as r,c as B,q as o,j as A,D as t,d as e,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"重启系统调用","description":"","frontmatter":{"title":"重启系统调用","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/restart-syscall.md","filePath":"cs/restart-syscall.md","lastUpdated":1791063341000}'),c={name:"cs/restart-syscall.md"};function p(m,a,D,h,f,T){const s=i("Mermaid");return r(),B("div",null,[a[2]||(a[2]=o('<h1 id="重启系统调用" tabindex="-1">重启系统调用 <a class="header-anchor" href="#重启系统调用" aria-label="Permalink to &quot;重启系统调用&quot;">​</a></h1><div class="epigraph"><p>可中断的慢系统调用被信号拽回用户态时，要么返回错误让库重试，要么由内核把 PC 拨回陷入指令再做一次。</p><footer>—— 据 Stevens and Rago, Advanced Programming in the UNIX Environment；Tanenbaum MOS 整理</footer></div><p><a href="/cs/copy-from-user">上一课</a>让入参进了内核副本，拷贝与实现都可以睡眠。<a href="/cs/signals">信号</a>会在返回用户前递送。缺口是：阻塞在 <code>read</code>、<code>wait</code> 上的线程被信号叫醒后，<strong>这次系统调用算完成、算失败，还是算没发生</strong>。本课钉重启约定，不重讲信号掩码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若一律返回「已做完」，调用方会把短读、未完成的 <code>wait</code> 当成功。若一律失败且不可重试，慢调用无法写成长逻辑。Unix 的折中：许多调用返回 <code>EINTR</code>，由用户库或程序决定是否重来；另一些在 <code>SA_RESTART</code> 一类标志下，内核把用户 PC 调回陷入指令，等于按原 ABI 再走一遍<a href="/cs/syscall-path">系统调用路径</a>。缺口是这条重启纪律，不是新的拷贝例程。</p><p>本课不把 POSIX 里每一条「哪些调用可重启」的表背完。</p><p><span class="marginnote">已经发生的副作用不能偷偷撤销：部分写入的字节已经在管道里。重启只适用于「要么没做、要么明确失败」的那一类，或由调用方对短操作自行循环。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>睡眠点被信号打断：若用户要求重启且该调用无不可逆副作用，则修改 trapframe 中的 PC（与必要时的调用号寄存器），返回用户后下一条就是原来的陷入。否则把错误码写入返回值槽，PC 指向陷入的下一条，由 libc 译成 <code>EINTR</code>。部分成功（短读）通常不当成重启对象：返回已传字节数。</p><p><span class="marginnote">术语翻译：「重启」就是内核替你重按一次「执行键」——信号到来时系统调用还没做完，内核在返回用户态前把 PC 改回那条陷入指令，应用感觉不到任何中断；不开重启则调用带着 <code>EINTR</code> 错误返回，「再试一次」变成应用自己的责任。</span></p><p><span class="marginnote">常见误区：初学者容易把「可重启」当成「一定会读到满缓冲」。重启只保证这次调用没有白做，而 <code>read</code> 本来就允许短读——信号、管道无数据、对端关闭都可能在传了几个字节后返回；要读满必须在自己的循环里继续调用，直到需要的字节数凑齐或出现真正的错误。</span></p>',11)),(r(),A(n,null,{default:t(()=>[l(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLEEP%5B%22%E9%98%BB%E5%A1%9E%E4%B8%AD%E7%9A%84%E8%B0%83%E7%94%A8%22%5D%20--%3E%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E9%80%92%E9%80%81%22%5D%0A%20%20SIG%20--%3E%20RST%5B%22%E6%94%B9%20PC%20%E5%86%8D%E9%99%B7%E5%85%A5%22%5D%0A%20%20SIG%20--%3E%20EINTR%5B%22%E8%BF%94%E5%9B%9E%E9%94%99%E8%AF%AF%22%5D%0A%20%20SIG%20--%3E%20SHORT%5B%22%E8%BF%94%E5%9B%9E%E5%B7%B2%E5%AE%8C%E6%88%90%E7%9A%84%E9%83%A8%E5%88%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("重启把「用户可见的一次 "),E("code",null,"read"),e("」与「内核内部被叫醒一次」分开。没有它，每个阻塞调用都要把信号检查写进应用循环。有了它，应用仍须处理短读写：重启不是无限重试直到满缓冲。与"),E("a",{href:"/cs/context-switch"},"上下文切换"),e("的关系：叫醒走唤醒，是否重启是返回用户前对 trapframe 的修补。")],-1)),a[5]||(a[5]=E("p",null,"拷贝已经成功的入参，重启时会再拷一次；这是可接受的重复，前提是用户指针语义仍成立。",-1)),(r(),A(n,null,{default:t(()=>[l(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22write%20%E5%B7%B2%E5%86%99%E5%85%A5%E7%AE%A1%E9%81%93%203%20%E5%AD%97%E8%8A%82%22%5D%20--%3E%20SIG%5B%22%E6%AD%A4%E6%97%B6%E4%BF%A1%E5%8F%B7%E5%88%B0%E6%9D%A5%22%5D%0A%20%20SIG%20--%3E%20Q%7B%22%E5%89%AF%E4%BD%9C%E7%94%A8%E8%83%BD%E5%81%87%E8%A3%85%E6%B2%A1%E5%8F%91%E7%94%9F%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%22%E5%90%A6%3A%20%E5%AD%97%E8%8A%82%E5%B7%B2%E5%9C%A8%E7%AE%A1%E9%81%93%E9%87%8C%22%20--%3E%20R%5B%22%E5%BF%85%E9%A1%BB%E8%BF%94%E5%9B%9E%203%2C%20%E4%B8%8D%E8%83%BD%E9%87%8D%E5%90%AF%E4%B9%9F%E4%B8%8D%E8%83%BDEINTR%22%5D%0A%20%20Q%20--%20%22%E6%98%AF%3A%20%E4%B8%80%E4%B8%AA%E5%AD%97%E8%8A%82%E9%83%BD%E6%B2%A1%E5%8A%A8%22%20--%3E%20A%5B%22%E5%8F%AF%E9%87%8D%E5%90%AF%3A%20PC%20%E6%8B%A8%E5%9B%9E%E9%87%8D%E6%96%B0%E5%81%9A%22%5D%0A%20%20A%20--%3E%20OK%5B%22%E5%BA%94%E7%94%A8%E6%97%A0%E6%84%9F%22%5D%0A%20%20R%20--%3E%20LOOP%5B%22%E5%BA%94%E7%94%A8%E5%BE%AA%E7%8E%AF%E7%BB%A7%E7%BB%AD%E5%86%99%E5%89%A9%E4%BD%99%E5%AD%97%E8%8A%82%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>这张图回答的问题是「信号打断时，内核凭什么决定走哪条出口」：判据是副作用。一个字节都没动，重启是安全的——重做一遍等于什么都没发生；已经写进去的 3 字节收不回来，重启会造成重复写入，于是只能如实返回已传数量，把收尾交给应用的循环。</p><p><span class="marginnote">数字实例：向管道写 100 字节，内核先放入 3 字节后被信号打断。若此时重启整个调用，管道里最终会出现 103 字节——多出的 3 字节正是重复副作用。正确行为是返回 3，应用再写 97；这就是「部分成功不重启」规则的由来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把实时信号排队、<code>signalfd</code> 写成另一接口课。也不讨论调试器单步时如何伪造重启。连接套接字上的超时与信号是后课网络路径，这里只保留 EINTR/重启二分。</p><p>后课默认：慢调用可被信号打断，重启或 <code>EINTR</code> 是 ABI 的一部分。若要把整条路径暴露给调试器与跟踪器，下一课讲跟踪与 ptrace 入口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信号可打断睡眠中的系统调用；重启或 <code>EINTR</code> 必须说清。</li><li>已发生的副作用不能假装没发生。</li><li>把路径暴露给跟踪器是下一课。</li><li>出处：Stevens and Rago, <em>APUE</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',7))])}const _=d(c,[["render",p]]);export{S as __pageData,_ as default};
